/* =============== b-fal-1 — آموزش فلسفه: پنجاه درس تکمیلی =============== */
const FAL1: Row[] = [
  ["چیستی شناخت؛ نخستین پرسش معرفت‌شناسی", "پیش از آنکه دربارهٔ هستی سخن بگوییم، باید بپرسیم: آیا اصلاً می‌توانیم چیزی را بشناسیم؟ معرفت‌شناسی — شناخت‌شناسی — همین پرسش را می‌کاوَد: شناخت چیست؟ ابزارش کدام است؟ و مرزهایش کجاست؟ مصباح یزدی در آموزش فلسفه، این بحث را درگاهِ ورود به فلسفه می‌داند؛ زیرا هر ادعای فلسفی — از اثبات خدا تا تجرد نفس — سرانجام به این پرسش بازمی‌گردد که «از کجا می‌دانی؟» و اگر پاسخی به آن نباشد، بنای فلسفه بر هواست.", ["شکاکیت و پاسخ آن", "شکاکان — از پیرون تا هوامِ دکارتی — گفته‌اند راهی به یقین نیست؛ اما خودِ همین ادعا، مدعیِ یقینی است که «یقین ممکن نیست» — و این تناقض، پاشنهٔ آشیل شکاکیتِ مطلق است. پاسخ فلسفهٔ اسلامی این است: شک، همواره در دل یقین‌هایی رخ می‌دهد؛ کسی که دربارهٔ همه‌چیز شک دارد، دست‌کم به شکِّ خود یقین دارد — و همین، نخستیی یقینِ حضوری است. از دل همین یقین، راه به دیگر شناخت‌ها باز می‌شود؛ پس شکاکیت، نه ایستگاه، که مرحلهٔ عبور است."]],
  ["شناخت حضوری و حصولی", "فلسفهٔ اسلامی، شناخت را به دو قسم بنیادین تقسیم می‌کند: «علم حصولی» — شناختی که با واسطهٔ صورت و مفهوم حاصل می‌شود، چون شناخت ما از درخت — و «علم حضوری» — شناختی که بی‌واسطه است و معلوم، خود، نزد عالم حاضر است، چون علم انسان به ترس و شادیِ خویش. این تقسیم، از شاهکارهای تحلیلی حکمت مشاء و صدرایی است؛ زیرا بسیاری از گره‌های معرفت‌شناسی — از مسئلهٔ عینیت شناخت تا علم خدا به جزئیات — با آن گشوده می‌شود.", ["چرا علم حضوری بنیادین است؟", "هر علم حصولی، سرانجام به علمی حضوری بازمی‌گردد: من تصویرِ درخت را می‌شناسم؛ اما اینکه «من این تصویر را می‌شناسم»، حضوری است — وگرنه زنجیرهٔ تصاویر، بی‌پایان می‌شد. علم به ذات نیز حضوری است: هر کس، پیش از هر شناختی، خود را می‌یابد؛ و این یافتن، نه با مفهوم و نه با استدلال، که با حضورِ خودِ خویش نزد خود است. این بنیاد — «علم نفس به ذات خود» — ستونِ برهان‌های تجرد نفس و پاسخ به مغزِ در بطریِ فلسفهٔ جدید است."]],
  ["اقسام جهل؛ جهل ساده و مرکب", "در برابر علم، جهل است — اما جهل نیز اقسام دارد: «جهل ساده» — ندانستن و آگاهی به ندانستن — که نه تنها عیب نیست، که آغاز دانش است؛ و «جهل مرکب» — ندانستن و پنداشتن که می‌دانم — که درمانش دشوارترین درمان‌هاست. منطق‌دانان، جهل مرکب را مانعِ اصلی تعقل شمرده‌اند؛ زیرا کسی که می‌پندارد می‌داند، نمی‌پرسد؛ و کسی که نمی‌پرسد، راهی به دانش نمی‌برد. در قرآن نیز، سرزنشِ اصلی، متوجه کسانی است که «لا یعلمون و یحسبون انهم یعلمون» — و این، تشخیصی روان‌شناختی-معرفت‌شناختی است که هزار و چهارصد سال، تازگی دارد.", ["درمان جهل مرکب", "درمان جهل مرکب، «اعتراف به ندانستن» است — همان که سقراط آن را آغاز فلسفه خواند و قرآن با «قل هل یستوی الذین یعلمون والذین لا یعلمون» راهش را گشود. در روش درسی حوزه‌ها، این درمان با «اشکال» آغاز می‌شود: شاگرد می‌آموزد که پیش از پذیرش، بپرسد و پیش از پاسخ، بشنود. و در سطح عمیق‌تر، جهل مرکب با «تمیز مفاهیم» درمان می‌شود: بسیاری از پندارهای دانش، خلط مفاهیم‌اند — و وقتی مفاهیم جدا شوند، پندار فرو می‌ریزد و جای خود را به پرسشِ راستین می‌دهد."]],
  ["بدیهیات و نظریات؛ معماری دانش", "دانش، ساختمانی است که همهٔ مصالحش از یک جنس نیست: «بدیهیات» — گزاره‌هایی که به‌محض تصور طرفین، تصدیق می‌شوند — چون «کل، از جزء بزرگ‌تر است»؛ و «نظریات» — گزاره‌هایی که برای تصدیق، به واسطهٔ استدلال نیاز دارند — چون «جهان، حادث است». هنر منطق و فلسفه، چیدن نظریات بر بدیهیات است — چنان‌که بنا، آجرها را بر سنگِ پی می‌چیند. هر دانشی، بدیهیاتِ خاص خود را دارد: ریاضی بر بدیهیات کمّی، فلسفه بر بدیهیات هستی‌شناختی؛ و دانشی که بدیهیاتش سست باشد، هرچه بالا برود، سست‌تر است.", ["اصول موضوعه و خطرِ بنای کج", "در هر دانشی، گزاره‌هایی هست که خودِ آن دانش آن‌ها را ثابت نمی‌کند، بلکه مفروض می‌گیرد — «اصول موضوعه» — چون فرضِ وجود جهان بیرونی در فیزیک. انتخاب این اصول، مهم‌ترین گزینش فلسفی هر دانش است؛ و بسیاری از اختلاف‌های میان مکاتب — چون تجربه‌گرایی و عقل‌گرایی — در حقیقت اختلاف بر سر اصول موضوعه است، نه نتایج. خوانندهٔ فلسفه باید بیاموزد که در هر دستگاهی، نخست بپرسد: این دانش چه چیزهایی را «فرض» کرده است؟ — و آنگاه ببیند که آیا ساختمان، بر سنگ نشسته است یا بر ماسه."]],
  ["صدق و کذب؛ معیار گزاره‌ها", "گزاره‌ها — اخبار — به صدق و کذب وصف می‌شوند؛ و صدق، در مشهورترین تعریف، «مطابقت حکم با واقع» است: می‌گویم برف می‌بارد؛ اگر در واقع ببارد، راست گفته‌ام. این تعریف — که «مطابقتی» خوانده می‌شود — ساده می‌نماید، اما پرسش‌ها را تمام نمی‌کند: «واقع» را چگونه بشناسیم تا انطباق را بسنجیم؟ و آیا صدقِ گزاره‌های ریاضی نیز از همین جنس است؟ فلسفهٔ اسلامی، با تفکیک مراتب واقعیت — عینی، ذهنی، لفظی — و با نظریهٔ «حکایت» و «انکشاف»، این بحث را ژرف کرده و نشان داده است که صدق، هم رابطه است و هم کاشفیت.", ["صدق در گزاره‌های اخلاقی و دینی", "پرسش دشوارتر، صدقِ گزاره‌های ارزشی است: «عدالت خوب است» — آیا این نیز حکایت از واقع است یا فقط ابراز احساس؟ واقع‌گرایان اخلاقی — که سنت اسلامی نیز بدان گرایش دارد — می‌گویند خوبی و بدی، واقعیتی دارند که عقل آن را درمی‌یابد؛ و این، پایهٔ «حسن و قبح عقلی» است که در کلام و اصول فقه، بنای حجیت عقل شد. خواننده می‌بیند که بحثِ ظاهراً انتزاعیِ صدق و کذب، چگونه به مسائل داغ اخلاق و دین می‌رسد: اگر گزاره‌های اخلاقی صدق و کذب نپذیرند، هیچ برهان اخلاقی‌ای، برهان نیست."]],
  ["علم نفس به ذات؛ بنیاد یقین", "از استوارترین یقین‌های انسان، علم او به خویش است — یقینی که هیچ شک، در آن راه نمی‌یابد. ابن‌سینا این یقین را با برهان مشهور «انسان معلق در فضا» نشان داد: اگر انسانی را در فضا معلق فرض کنیم — بی هیچ حس و حرکت و برخورد — باز به وجود خویش علم دارد؛ پس خودِ انسان، چیزی جز بدن و قوای حسی است. این برهان، از شاهکارهای فلسفهٔ اسلامی است؛ زیرا بی‌هیچ مقدمهٔ تجربی، به جوهری بودن نفس می‌رسد — و هفت قرن بعد، دکارت با کوگیتو راهی مشابه پیمود، بی‌آنکه از ابن‌سینا بی‌خبر بوده باشد — که بسیاری، شباهت دو برهان را گواهِ وحدتِ پرسش‌های بنیادین بشر دانسته‌اند.", ["پیامدهای علم حضوری به نفس", "از علم حضوری نفس به ذات، پیامدهای بزرگی می‌گیرد: نخست، «تجرد» — نفس، در این یافتن، نه مکان دارد و نه کمیت؛ پس از جنس ماده نیست. دوم، «وحدت شخصیه» — منِ امروز، همان منِ ده سال پیش است که خاطراتش را به خود نسبت می‌دهم؛ و این همانی، در جسمِ دگرگون‌شونده یافت نمی‌شود. سوم، «آزادی» — کسی که خود را می‌یابد و بر فعل‌هایش اشراف دارد، در همان یافتن، خود را مختار می‌یابد. این سه پیامد، ستون‌های فلسفهٔ نفس‌اند — و هر سه، از یک یقینِ ساده برمی‌خیزند: من، هستم."]],
  ["شک و مراتب آن؛ از غزالی تا دکارت", "شک، ابزار است، نه مقصد — اما ابزارها نیز مراتب دارند. غزالی در «المنقذ من الضلال»، شک را روشی برای رسیدن به یقین آزمود و دریافت که حواس و حتی بدیهیات عقل، قابل پرسش‌اند — و سرانجام، یقین را نه در برهان، که در «نوری که خدا در دل می‌افکند» یافت. سه قرن بعد، دکارت همین راه را پیمود: همه‌چیز را شک کرد تا به «می‌اندیشم پس هستم» رسید. خوانندهٔ فلسفهٔ اسلامی، با دیدن این هم‌مسیری، می‌آموزد که شکِ روشی، میراث مشترک بشر است — و تفاوت مکاتب، نه در شک، که در «جایی است که شک، می‌ایستد».", ["حدِّ ایستادن شک", "شکِ روشی، در جایی باید بایستد — وگرنه خود را ویران می‌کند. غزالی، حد را در نور الهی دید و دکارت در کوگیتو و سپس در خدای صادق؛ و فلسفهٔ صدرایی، در علم حضوری نفس و بدیهیات فطری. معیار این حد — که هر مکتبی به سبکی می‌گوید — این است: شک، باید به یقینی برسد که شک در آن، «عملی» نباشد — یعنی نتوان با آن زندگی و اندیشه را ساخت. خواننده باید این معیار را با خود داشته باشد؛ زیرا در روزگاری که شک، خود به سبک زندگی بدل شده، دانستنِ «حدّ شک»، از خودِ شک مهم‌تر است."]],
  ["معیار حقیقت؛ ترازوی شناخت‌ها", "اگر شناخت‌ها گوناگون‌اند — حسی، عقلی، شهودی — با چه ترازویی میان آن‌ها داوری کنیم؟ تاریخ فلسفه، سه پاسخ بزرگ داده است: «مطابقت» — حقیقت، انطباق با واقع است؛ «انسجام» — حقیقت، سازگاری نظام باورهای ماست؛ و «کارکرد» — حقیقت، آنچه در عمل می‌سازد. فلسفهٔ اسلامی، با اصالت دادن به مطابقت، از دو دیگر نیز بهره می‌گیرد: انسجام، نشانهٔ صدق است و کارکرد، میوهٔ آن — اما هیچ‌یک، جای مطابقت را نمی‌گیرد؛ زیرا نظامی منسجم می‌تواند — چون افسانهٔ دقیق — با واقع ناسازد، و آنچه می‌سازد، می‌تواند فریب باشد.", ["کثرت ابزار و وحدت معیار", "نکتهٔ ظریف این است که معیارِ واحد، ابزارِ متعدد می‌پذیرد: حس، ابزار شناخت محسوسات است؛ عقل، ابزار معقولات؛ و دل — به تعبیر عارفان — ابزار شهودیات. خطای بزرگ مکاتب، یکی کردنِ این ابزارهاست: تجربه‌گرایی، عقل را به حس فروکاست و عقل‌گراییِ افراطی، حس را از اعتبار انداخت. حکمت متعالیه، با نظریهٔ مراتب وجود، مراتب شناخت را نیز توجیه می‌کند: هر مرتبه از هستی، ابزارِ شناختِ خود را می‌طلبد — و داوریِ درست، داوریِ «کجا و با چه» است، نه داوریِ یک‌چشم."]],
  ["تعریف و اقسام آن؛ هنر مرزگذاری", "بسیاری از اختلاف‌های فلسفی، در حقیقت اختلاف بر سر تعریف‌هاست — و از این روست که منطق، «تعریف» را از نخستین مهارت‌های اندیشیدن شمرده است. تعریف، «قول شارح» است — سخنی که حقیقت چیزی را می‌نمایاند؛ و کامل‌ترین آن، «حدّ تام» است: genus و فصل — جنس نزدیک و فصل نزدیک — چون «انسان، حیوانِ ناطق است». در برابر، «رسم» است — تعریف با لوازم و خواص — و «شرح الاسم» — توضیح لفظ. هنر فیلسوف، یافتن فصل‌هاست — مرزهایی که حقیقت را از غیرش جدا می‌کنند؛ و بسیاری از گره‌های کلامی و حقوقی، با همین مهارت گشوده می‌شود: وقتی مفاهیم مرزبندی شوند، نزاع‌ها، یا حل می‌شوند یا معلوم می‌شود که نزاعی نیست.", ["آفات تعریف", "برای تعریف، آفاتی شمرده‌اند: دور — تعریف چیزی به خودش —، تسلسل — زنجیرهٔ بی‌پایان تعاریف —، و تعریف به اخفی — روشن کردن چیز روشن به چیز تاریک‌تر. و آفتِ پنهان‌تر، «تعریف‌های احساسی» است: تعریفهایی که نه حقیقت، که موضع گوینده را می‌نمایانند — چون تعریفِ «عدالت» به «هرچه من می‌خواهم». خوانندهٔ متون فلسفی باید بیدار باشد که فیلسوف، مفاهیم کلیدی‌اش را چگونه تعریف می‌کند؛ زیرا بسیاری از نتایجِ شگفت‌انگیز، نه از برهان، که از تعریفِ پیشاپیش-گزیده برخاسته‌اند — و نقد دستگاه‌ها، گاه نه نقد برهان، که نقد تعریف است."]],
  ["استدلال و اقسام آن؛ راه‌های رسیدن", "استدلال، حرکت ذهن از معلوم به مجهول است — و راه‌های این حرکت، گوناگون‌اند: «استقرا» — از جزئیات به کلی — چون رسیدن از دیدن صدها قو به «قوها سپیدند»؛ «تمثیل» — از جزئی به جزئیِ دیگر — چون سنجش حکم دو پروندهٔ مشابه؛ و «قیاس» — از کلی به جزئی — که تنها راهِ یقین‌آور شمرده می‌شود. منطق صوری، عمدتاً منطق قیاس است؛ زیرا استقرا — بی‌آنکه کامل باشد — یقین نمی‌آورد و تمثیل، گمان می‌سازد. اما علوم جدید، عمدتاً بر استقرای ناقص‌اند — و این، از مهم‌ترین بحث‌های فلسفهٔ علم است که حدّ اعتبارِ علم تجربی را روشن می‌کند.", ["قیاس و صناعات خمس", "قیاس‌ها بر پایهٔ مقدمات‌شان، به پنج صنعت تقسیم می‌شوند: «برهان» — از یقینیات، و هدفش آموزش حقیقت است؛ «جدل» — از مشهورات و مسلمات، برای الزام خصم؛ «خطابه» — برای اقناع عامه؛ «شعر» — برای انگیختن تخیل؛ و «مغالطه» — که به ظاهر، برهان است. شناخت این پنج، مهارتی حیاتی برای خوانندهٔ امروز است؛ زیرا در فضای رسانه، جدل و خطابه و شعر، غالباً در لباس برهان می‌آیند — و کسی که این لباس‌ها را نشناسد، فریبِ صنعت‌ها را می‌خورد. منطق، در این سطح، نه درسِ انتزاعی، که واکسنِ فریب است."]],
  ["مغالطات؛ دام‌های اندیشه", "مغالطه، استدلالی است که به ظاهر درست می‌نماید اما نیست — و شناخت مغالطات، نیمهٔ دیگر منطق است. از مشهورترین‌ها: «مصادره به مطلوب» — گرفتن نتیجه در مقدمات؛ «حمله به شخص» — داوری دربارهٔ گوینده به‌جای گفته؛ «پهلوان‌پنبه» — تحریف سخن خصم سپس کوبیدن آن؛ «توسل به اکثریت» — درست انگاشتن چیزی چون بسیاری گفته‌اند؛ و «شیب لغزنده» — پرش از گام کوچک به فاجعهٔ بزرگ. فلسفهٔ اسلامی، این‌ها را زیر عنوان «مغالطات لفظی و معنوی» — چون اشتراک لفظ و اجتماع و افتراق — سامان داده و نشان داده است که ریشهٔ بسیاری از مغالطات، در زبان است: واژه‌ای که دو معنا دارد، پلی می‌شود برای پرش از این معنا به آن.", ["چرا مغالطه می‌کنیم؟", "مغالطه، هم خطاست و هم فریب — و فریب، تنها فریب دیگران نیست: انسان، بیش از همه، مغالطه‌گرِ خویش است. روانشناسی جدید، این را «سوگیری شناختی» خوانده است — از سوگیری تأیید تا اثر هاله‌ای — و ریشهٔ آن را در اقتصادِ ذهن دانسته: ذهن، می‌خواهد زود نتیجه بگیرد. درمان، همان است که منطق کلاسیک گفته: کُند شدن — بازجوییِ مقدمات پیش از پذیرش نتیجه. خواننده‌ای که این درس را جدی بگیرد، در برابر تبلیغ، شعار و حتی استدلال‌های خودش، مصونیتی می‌یابد که هیچ ابزاری جای آن را نمی‌گیرد."]],
  ["وجود و ماهیت؛ دو وجه هر چیز", "هر چیزی که می‌شناسیم، دو وجه دارد: «چیستی» — ماهیت — چون انسانیتِ انسان؛ و «هستی» — وجود — چون این-که-هست. فلسفهٔ اسلامی، این تفکیک را — که ریشه در ابن‌سینا دارد — ستون متافیزیک خود کرده است؛ زیرا از آن، مهم‌ترین بحث‌ها برمی‌خیزد: آیا وجود، امری زاید بر ماهیت است یا خودِ حقیقتِ آن؟ و واجب‌الوجود، کیست؟ ابن‌سینا گفت در همهٔ ممکنات، وجود بر ماهیت زاید است — جز در خدا که وجودش، عین ذات اوست — و این تقریر، بنای برهان وجوب و امکان شد.", ["دو نگاه به این تفکیک", "این تفکیک، دو خوانش بزرگ یافت: مشهور شد که ابن‌سینا و پیروانش، وجود را «امری اعتباری» و ماهیت را «اصیل» دانستند — مبنایی که به اصالت ماهیت خوانده می‌شود؛ اما صدرالمتألهین این خوانش را واژگون کرد و گفت آنچه در خارج است، وجود است و ماهیت، حدّ و سایهٔ آن — «اصالت وجود». این اختلاف، اختلافی بر سر واژه نیست: اگر ماهیت اصیل باشد، جهان، مجموعهٔ چیزهای جداست؛ و اگر وجود اصیل باشد، جهان، دریای واحدی است که چیزها، موج‌های آن‌اند. از این دو نگاه، دو جهان‌بینی می‌روید — و سیر فلسفهٔ اسلامی، تا حد بزرگی، سیرِ روشن شدن این دو نگاه است."]],
  ["اصالت وجود یا اصالت ماهیت", "مهم‌ترین بحث متافیزیک صدرایی، «اصالت وجود» است: در خارج، جز وجود، چیزی نیست — ماهیت، حدِّ وجود است، نه شریک آن. دلایل صدراییان: نخست، اثرها — آنچه در خارج اثر می‌کند، وجود است: آتش می‌سوزاند چون هست، نه چون آتشیت دارد. دوم، تشکیک — وجود، مراتب دارد و یک حقیقتِ واحد است؛ اما ماهیات، متباین‌اند و نمی‌توانند مرتبهٔ یک حقیقت باشند. سوم، اعتباریات — مفاهیمی چون کلیت و جزئیت، بر ماهیت عارض می‌شوند و وجود را فرا نمی‌گیرند؛ پس وجود، فراتر از ماهیت است. این دلایل، جهان‌بینی را دگرگون می‌کنند: هستی، یکی است و متشکک — و کثرت، در حدود است، نه در خودِ هستی.", ["پیامدهای اصالت وجود", "از اصالت وجود، نتایج بزرگی می‌گیرد: حرکت جوهری — جوهر، وجودِ سیال است؛ علم حضوری — علم، حضور وجود است؛ و وحدتِ وجودِ عارفانه، تقریر فلسفی می‌یابد — بی‌آنکه با پانتهیسم خلط شود. و مهم‌تر از همه، خداشناسی: خدا، وجودِ محض است — بی هیچ حدّ و ماهیت — و از این روست که «لیس کمثله شیء» — نه از این رو که ما او را نمی‌شناسیم، که از این رو که هیچ «چیستی»‌ای، گنجایش او را ندارد. خواننده‌ای که اصالت وجود را فهمید، کلید بسیاری از مباحث صدرایی — از معاد تا عرفان — را در دست دارد؛ و بدون آن، حکمت متعالیه، زبانی بی‌الفباست."]],
  ["تشکیک وجود؛ یک حقیقت، مراتبِ بسیار", "تشکیک، نظریه‌ای است که می‌گوید وجود، یک حقیقتِ واحد است که مراتبِ شدت و ضعف دارد — چون نور که در خورشید و شمع، یکی است و متفاوت. ابن‌سینا، تشکیک را به وجود نسبت نداد و آن را از ویژگی‌های ماهوی شمرد؛ اما صدرالمتألهین، تشکیک را قلب متافیزیک خود کرد: وجود، مشکک است — «حقیقت واحده ذات مراتب». معنای دقیق: وجود، جنس نیست که فصول بپذیرد؛ و نوع نیست که افرادش هم‌رتبه باشند؛ بلکه حقیقتی است که عیناً در مرتبهٔ شدید و ضعیف هست — و تفاوت مراتب، عین ارتباط است: مرتبهٔ ضعیف، «عین الربط» به مرتبهٔ شدید است.", ["تشکیک و حل مسئله کثرت", "تشکیک، پاسخی است به کهن‌ترین پرسش متافیزیک: چگونه از یکی، بسیار برمی‌خیزد؟ اگر وجود، حقیقتی یکسان و بی‌مرتبه بود، یا باید یکی بیش نباشد یا کثرتش بی‌دلیل؛ اما وجودِ مشکک، کثرت را در دل وحدت می‌نشاند: هر مرتبه، همان وجود است به حدّی — و سلسلهٔ مراتب، نه پاره‌های یک کل، که ظهورهای یک حقیقت‌اند. این نگاه، در کلام، مسئلهٔ خالق و مخلوق را بازتعریف می‌کند: مخلوق، «چیزِ جدا» از خالق نیست که شریکش باشد؛ ظهورِ محدودِ اوست — و همین، راه را برای فهمِ «خلق از عدم» و «قیام وجودی مخلوقات» می‌گشاید."]],
  ["وحدت و کثرت؛ مسئلهٔ نخستین", "پیش از سقراط، فلسفه با این پرسش آغاز شد: آیا جهان، یکی است یا بسیار؟ پارمنیدس، یکی گفت و کثرت را سراب خواند؛ و تجربیون، بسیار گفتند و وحدت را نام‌گذاری. افلاطون کوشید با مثل، و ارسطو با ماده و صورت، میان این دو آشتی دهد — و فلسفهٔ اسلامی، با تشکیک و اصالت وجود، این آشتی را به اوج رساند: جهان، از حیث اصلِ هستی، به سوی وحدت می‌رود و از حیث حدود، کثیر است. این مسئله، تنها بحث انتزاعی نیست: وحدت و کثرت، در جامعه — فرد و جمع —، در دین — شریعت و حقیقت — و در هنر — اجزا و کل — نیز پرسشِ اول است.", ["اقسام وحدت", "وحدت، اقسام دارد که خلط آن‌ها، منشأ بسیاری از نزاع‌هاست: «وحدت عددی» — یکی بودن فرد، چون یک انسان؛ «وحدت نوعی» — یکی بودن در چیستی، چون همهٔ انسان‌ها؛ «وحدت جنسی» — یکی بودن در جنس؛ «وحدت ارتباطی» — یکی بودن اجزای یک نظام، چون بدن؛ و «وحدت حقیقی» — یکی بودن خودِ حقیقت، که تنها در وجودِ واجب یافت می‌شود. عرفا وقتی از وحدت وجود سخن می‌گویند، مقصودشان قسم آخر است — و کسانی که بر آنان اشکال می‌کنند، غالباً وحدت عددی می‌فهمند. این درس، نمونه‌ای است از اینکه چگونه «تمیز مفاهیم»، نزاع‌های چند قرنه را گره‌گشایی می‌کند."]],
  ["جوهر و عرض؛ ساختمان هستی", "فلسفهٔ مشاء، هستی را به دو قسم تقسیم می‌کند: «جوهر» — آنچه در خارج، در موضوع نیست و قائم به ذات است، چون جسم و نفس — و «عرض» — آنچه برای بودن، به موضوع نیاز دارد، چون رنگ و علم. مقولات، سرشماری اقسام هستی‌اند: یک جوهر و نه عرض — کم، کیف، اضیفه، مکان، زمان، وضع، ملک، فعل و انفعال. این نقشه، دو هزار سال، زبان فلسفه و کلام بود؛ و حتی فقه — در بحث‌هایی چون «آیا علم و رنگ، قابل تملک‌اند؟» — از آن بهره برده است. خواننده باید این نقشه را — با همهٔ نقد‌هایی که بر آن شده — بشناسد؛ زیرا زبان متون کلاسیک، زبان مقولات است.", ["نقد صدرایی بر مقولات", "صدرالمتألهین، بر این نقشه، نقدهای بنیادین وارد کرد: نخست، اینکه مقولات، سرشماری هستی نیست، سرشماری مفاهیم است — و وجود، پیش از هر تقسیم، یک حقیقت است. دوم، اینکه برخی مقولات — چون زمان و مکان — وجودِ مستقل ندارند؛ زمان، نه ظرفِ حرکت، که وجهِ حرکت است. سوم، اینکه نفس، در دستگاه مقولات نمی‌گنجد — نه جوهر جسمانی است و نه عرض — و این، خود، برهان دیگری بر تجرد است. این نقدها، نه ویرانی نقشهٔ قدیم، که گشودن افقی نو بود: از «هستی به‌مثابه طبقه‌ها» به «هستی به‌مثابه مراتب یک جریان»."]],
  ["تقابل؛ تضادها چگونه می‌ایستند؟", "تقابل، رابطهٔ میان دو امر است که جمع‌نشدنی‌اند — و اقسام دارد: «تناقض» — هستی و نیستی — که اصلِ همهٔ تقابل‌هاست؛ «تضاد» — سیاهی و سپیدی در یک موضوع؛ «تضايف» — پدری و پسری؛ و «عدم و ملکه» — کوری و بینایی در جایی که شأن بینایی هست. شناخت این اقسام، ظرافت‌های استدلال را روشن می‌کند: مثلاً برهانِ «اجتماع نقیضین محال است»، بنای همهٔ برهان‌هاست؛ و خلط تضاد با تناقض — چون گفتنِ «خیر و شر، تناقض‌اند» — به خطاهای بزرگ در مسئلهٔ شر می‌انجامد. تقابل، در دیالکتیک نیز بازخوانی شد — اما دیالکتیک هگلی، تقابل را در دل واقعیت دید، نه در دل ذهن؛ و این، نقطهٔ افتراق منطق کلاسیک و فلسفهٔ جدید است.", ["عدم و ملکه؛ پرکاربردترین تقابل", "در علوم انسانی و اخلاق، پرکاربردترین تقابل، «عدم و ملکه» است: عدالت، تقابلش ظلم است — نه به معنای تضاد، که به معنای نداشتنِ آنچه باید داشت. از این روست که بسیاری از رذایل، «نداشتن»‌اند — نه «داشتن»‌های منفی: جهل، نبودِ علم است؛ و کوریِ دل، نبودِ بصیرت. این نگاه، نسخهٔ عملی دارد: درمان رذیلت، نه جنگیدن با سایه، که افروختنِ نورِ فضیلت است — چنان‌که نراقی در معراج السعادة می‌گوید فضایل و رذایل، ملکه‌های نفس‌اند و نفس، با فضیلت، پر می‌شود و جای رذیلت تنگ. این، اخلاقِ ساختن است، نه اخلاقِ جنگیدن."]],
  ["قوه و فعل؛ هستیِ در حرکت", "ارسطو، برای فهم تغییر، دو مفهوم ساخت: «قوه» — تواناییِ بودنِ چیزی — و «فعل» — بالفعل بودن آن. دانه، درخت است بالقوه؛ و درخت، بالفعل. این دو مفهوم، راه را بر پارادکس‌های پارمنیدس بست: تغییر، نه شدنِ هست از نیست، که فعلیت یافتنِ قوه‌هاست. ابن‌سینا این دستگاه را در فلسفهٔ اسلامی گسترش داد و از آن، در برهان‌های هستی‌شناسانه بهره جست: هر چه بالقوه است، برای فعلیت، به فعلی نیاز دارد — و این زنجیره، سرانجام به فعلِ محض می‌رسد که هیچ قوه‌ای ندارد — خدا. قوه و فعل، پس از دو هزار سال، هنوز در فلسفهٔ ذهن — مسئلهٔ استعدادها و توانایی‌ها — و در الهیات — مسئلهٔ حدوث و قدم — کار می‌کند.", ["قدم زمانی و ذاتی", "از ظریف‌ترین کاربردهای قوه و فعل، تفکیک «قدم زمانی» از «قدم ذاتی» است: جهان، از نظر زمانی، آغاز دارد یا ندارد — بحث کلام —؛ اما از نظر ذاتی، هر لحظه، «امکان» دارد — یعنی برای بودن، در همان لحظه، به علّت نیاز دارد؛ چنان‌که نور خورشید، هر لحظه، به خورشید نیاز دارد — حتی اگر همیشه بوده باشد. این تفکیک، بحث حدوث و قدم را از بن‌بست زمانی بیرون آورد: پرسش اصلی، نه «جهان کی آغاز شد؟» که «جهان، از کجا هستی می‌گیرد؟» است — و پاسخ این پرسش، هم بر جهانِ حادث صادق است و هم بر جهانِ فرضاً قدیم."]],
  ["حرکت و اقسام آن", "حرکت، خروج تدریجی از قوه به فعل است — و اقسام دارد: حرکت در کم — رشد و نقصان؛ در کیف — چون گرم شدن؛ در مکان — جابه‌جایی؛ و در وضع — چون چرخش. مشائیان، حرکت را تنها در این چهار مقوله می‌دانستند و در جوهر، حرکت را انکار می‌کردند — زیرا جوهر، پایهٔ ثبات است؛ اگر جوهر هم تغییر کند، چه چیز، هویت را نگه می‌دارد؟ این انکار، بیش از دو هزار سال، از بدیهیات فلسفه بود — تا صدرالمتألهین، با «حرکت جوهری»، آن را شکست و گفت: جوهرِ جهان مادی، عین حرکت است — و ثبات، نه در ذات جوهر، که در نفسِ حرکت است؛ چنان‌که ثبات رود، در جاری بودن اوست.", ["پاسخ به شبههٔ هویت", "شبههٔ اصلی در برابر حرکت جوهری، شبههٔ هویت است: اگر جوهر من هر لحظه دگرگون است، منِ امروز، همان منِ دیروز نیست — پس مسئولیت و خاطره و وعد و وعید، بی‌معنا می‌شود. پاسخ صدرایی، دوگانه است: نخست، حرکت، نه تعویض اجزا، که «تجدد حدود یک وجود واحد» است — وجود، در طول حرکت، یکی می‌ماند و حدودش نو می‌شود؛ و دوم، هویتِ انسان، نه به بدنِ دگرگون، که به نفسِ مجرد است که در طول حرکت، قوام می‌یابد و «با بدن، از قوه به فعل می‌رود». این پاسخ، مسئلهٔ هویت را از فلسفهٔ طبیعت به فلسفهٔ نفس منتقل می‌کند — جایی که واقعاً جای آن است."]],
  ["حرکت جوهری؛ انقلاب صدرایی", "حرکت جوهری — سیلان ذات جوهر مادی — از جسورترین نظریه‌های صدرالمتألهین است. دلایل او: نخست، وجود، عین تشکیک و سیلان است و هیچ حدّی از هستی، در ماده، ساکن نمی‌ایستد. دوم، اعراض — چون رنگ و کیفیت — ذاتاً وابسته‌اند؛ و وابستگیِ دگرگون‌شونده، به پایهٔ دگرگون‌شونده است — عرض، سایهٔ جوهر است و سایهٔ متحرک، از جوهرِ متحرک می‌آید. سوم، نفس انسان — که پیدایشش از ماده و بقایش در تجرد است — تنها با حرکت جوهری قابل تبیین است: نفس، از دلِ حرکتِ جوهریِ بدن، «برمی‌خیزد» — جسما الحدوث و روحانیا البقا. این نظریه، پلی است میان طبیعت و ماورا؛ و بی‌آن، فلسفهٔ صدرایی، نیمه‌تمام است.", ["پیامدهای حرکت جوهری", "از حرکت جوهری، نتایج بزرگی برمی‌خیزد: زمان، نه ظرف، که «مقدار حرکت جوهری» است — و با آن، مسئلهٔ قدم و حدوث جهان، رنگی تازه می‌گیرد. معاد، نه بازگشت به بدنِ کهنه، که «به فعل رسیدنِ بدنِ برزخی» است. و عالم مثال — جهان صورت‌های مجرد از ماده — نه افزوده‌ای شاعرانه، که لازمِ حرکتِ جوهری است: چیزی که از قوه به فعل می‌رود، صورتِ فعلی‌اش، پیش از تحقق کامل، در مرتبه‌ای میانی هست. خواننده می‌بیند که یک نظریهٔ طبیعی — حرکت — چگونه متافیزیک، معادشناسی و عرفان را با هم بازسازی می‌کند — و این، معنای «نظام فلسفی» است."]],
  ["زمان و مکان؛ ظرف یا وجه؟", "زمان چیست؟ ارسطو گفت زمان، «عددِ حرکت به اعتبار قبل و بعد» است — نه خودِ حرکت، نه چیزی جدا از آن. صدرالمتألهین این را ژرف کرد: زمان، وجهی از وجودِ متحرک است — نه ظرفی که حرکت در آن است؛ و مکان، نه خلأ، که «سطح درونیِ جسمِ محیط» است. این نگاه، پرسش‌های کهنه را پاسخ می‌دهد: آیا زمان، پیش از جهان بود؟ — نه؛ زیرا زمانی نیست بی حرکت؛ و آیا برای خدا «قبل و بعد» هست؟ — نه؛ زیرا او فراتر از حرکت است — و این، معنای «قدم» ذاتی اوست. در فلسفهٔ جدید نیز، کانت زمان و مکان را «صورِ شهود» خواند — قالب‌های ذهن — و این، با نگاه صدرایی — وجهِ وجود، نه ظرف — هم‌مسیر است: زمان، شیء نیست؛ افقِ دیده شدنِ اشیاست.", ["زمان و ابدیت", "مقابل زمان، «ابدیت» است — و مقابل ابدیت، «دهر». در فلسفهٔ اسلامی، ابدیت، نداشتنِ آغاز و فرجام با تدریج است — زمانِ بی‌پایان —؛ اما «سرمد»، نداشتنِ زمان از ریشه است — و از آنِ ذاتِ واجب است؛ و «دهر» — که صدراییان بدان اهمیت دادند — مرتبه‌ای است میان زمان و سرمد: جهانِ عقول و مثال، که تغییرِ ذاتیِ تدریجی ندارد اما ثباتِ محضِ سرمدی نیز ندارد. این سه مرتبه — زمان، دهر، سرمد — نقشه‌ای است که مسئلهٔ «خدا و زمان» را حل می‌کند: خدا در زمان نیست که پیر شود، و بی‌رابطه با زمان نیست که جهان را نداند؛ او در سرمد است — و سرمد، بر زمان محیط است، چنان‌که خطِ عمود، بر نقاطِ خط."]],
  ["ماده و صورت؛ ترکیب اشیاء", "هر جسم، ترکیبی است از «ماده» — قوهٔ پذیرش — و «صورت» — فعلیتِ آن. آب، ماده‌ای است که صورتِ آبی دارد؛ و اگر صورتش به صورت بخار بدل شود، ماده، همان می‌ماند. این ترکیب — هیولی و صورت — پاسخ ارسطو به پرسش تغییر بود: آنچه تغییر می‌کند، صورت است؛ و آنچه می‌ماند، ماده. اما مادهٔ اولی چیست؟ — نه خود جسم است، چون جسم، صورت دارد؛ و نه هیچ است، چون پذیرای صورت‌هاست. ابن‌سینا، مادهٔ اولی را «قوهٔ محض» خواند — چیزی که جز پذیرایی، هیچ نیست. و صدرالمتألهین، با حرکت جوهری، ماده را نه پایهٔ ساکن، که «جریانِ قوه» خواند — و این، ماده را از سکونِ ارسطویی به سیلانِ صدرایی برد.", ["صورت‌های مجرد", "در برابر صور مادی، «صور مجرد»‌اند — صورت‌هایی که نه در ماده‌اند و نه وابسته به آن: صور عقلی — چون مفهوم انسانیت — و صور مثالی — چون صورت‌های عالم برزخ. برهان تجرد این صور، از راه علم می‌گذرد: اگر صورتِ علمی، مادی بود، باید در مکان بود و تقسیم‌پذیر — و حال آنکه مفهوم «انسانیت»، نه مکان دارد و نه نصف می‌شود. این بحث، پل فلسفهٔ اسلامی به عالم مثال است — جهانی که نه ماده دارد و نه مجردِ محض است؛ و از این رو، جایگاه خواب‌های صادقه، مکاشفات و معاد جسمانی است. خواننده‌ای که صور مجرد را فهمید، نیمی از راهِ فهم معاد را پیموده است."]],
  ["علیت؛ ستون جهان", "جهان، بی‌علت چیزی را نمی‌پذیرد — «هر حادثی، علّت می‌خواهد» — و این، از بنیادی‌ترین بدیهیات عقل است که حتی انکارکنندگانش — چون هیوم — در عمل بدان متکی‌اند. علیت، یعنی «نیاز وجودی معلول به علّت» — نه صرف توالی رویدادها؛ و این تفاوت، همه‌چیز است: اگر علیت، فقط توالیِ عادت‌شده باشد — چنان‌که هیوم گفت — علم، پیش‌بینیِ عادت است، نه شناخت جهان؛ اما اگر علیت، پیوند وجودی است، علم، کشفِ بافتِ واقع است. فلسفهٔ اسلامی، علیت را با «اصالت وجود» و «سنخیت» — هر معلولی، سنخِ علّت خویش را دارد — تکمیل کرد: معلول، ظهورِ علّت است؛ و از این روست که جهان، آیینهٔ مبدعش خوانده می‌شود.", ["علل چهارگانه", "ارسطو، علّت را به چهار قسم شمرد: «مادی» — آنچه از آن ساخته می‌شود؛ «صوری» — آنچه به شکل آن است؛ «فاعلی» — آنچه می‌سازد؛ و «غایی» — آنچه برای آن ساخته می‌شود. علم جدید، علل غایی و صوری را از طبیعت بیرون کرد و تنها فاعلی و مادی را نگه داشت — و این گزینش، نه کشف، که «تصمیم روش‌شناختی» بود که پیامدهای بزرگی داشت: طبیعت، بی‌جهت شد؛ و پرسش «برای چه؟» از علم به فلسفه تبعید شد. حکمت متعالیه، غایت را نه فقط در صنع انسان، که در خود طبیعت می‌بیند — و این، از آن رو مهم است که پرسش‌های معنای زندگی، بی بازگشتِ «برای چه»، بی‌پاسخ می‌مانند."]],
  ["سنخیت؛ چرا این علّت، این معلول", "قاعدهٔ سنخیت می‌گوید: میان علّت و معلول، سنخیتی است — «الواحد لا یصدر عنه الا الواحد» و «از هستی، هستی برمی‌خیزد». این قاعده، پاسخ فلسفهٔ اسلامی به پرسش «چرا از هر چیزی، هر چیزی برنمی‌خیزد؟» است: آتش، نمی‌سوزاند چون ما عادت کرده‌ایم — چون در آتش، سنخِ سوزانندگی هست. سنخیت، در معرفت‌شناسی نیز کار می‌کند: شناختِ ما از جهان، ممکن است چون میان ذهن و جهان، سنخیتی هست — هر دو، وجودند. و در الهیات، سنخیت، راه را بر «خلق از عدمِ محض» — بی هیچ سنخیت — می‌بندد و می‌گوید: جهان، از «فیض» است — ظهوری که سنخِ مبدعش را دارد، بی‌آنکه عین او باشد.", ["سنخیت و پاسخ به هیوم", "هیوم گفت ما از علیت، جز توالی و اقتران نمی‌بینیم — و از این رو، علیت، عادت ذهن است، نه واقع. پاسخ سنخیتی این است: هیوم، علیت را در «مشاهده» جست و نیافت — اما علیت، امر مشاهده نیست، امر تعقل است: ما با عقل می‌فهمیم که ممکن‌الوجود، برای بودن، به غیر نیاز دارد — و این فهم، پیش از هر مشاهده است. این اختلاف، نمونهٔ کلاسیک اختلاف تجربه‌گرایی و عقل‌گرایی است — و خواننده باید بداند که علم جدید، عملاً از هر دو بهره می‌گیرد: مشاهده، داده می‌دهد؛ اما ساختارِ قانونمندِ داده‌ها — که علیت را می‌سازد — از عقل می‌آید؛ و کانت، بعدها، همین نکته را نظام‌مند کرد."]],
  ["ضرورت و امکان؛ سه‌گانهٔ هستی", "هر گزارهٔ هستی‌شناختی، یکی از سه وضع را دارد: «واجب» — که نمی‌تواند نباشد؛ «ممتنع» — که نمی‌تواند باشد؛ و «ممکن» — که بودن و نبودنش، به خودی خود، برابر است. این سه‌گانه، بنای برهان وجوب و امکان است: جهان، ممکن است — زیرا می‌توانست نباشد و دگرگونه باشد؛ و ممکن، برای ترجیح یکی از دو طرف، به مرجح نیاز دارد؛ و این زنجیرهٔ مرجح‌ها، سرانجام به موجودی می‌رسد که خودش ممکن نیست — واجب. این برهان، از محکم‌ترین برهان‌های الهیات فلسفی است؛ زیرا نه بر نظم تکیه دارد — که قابل انکار است — نه بر حدوث زمانی — که بحث‌انگیز است — که بر خودِ «امکان» تکیه دارد — بر اینکه هر چه هست، جز خدا، «می‌توانست نباشد».", ["امکان فقری", "صدرالمتألهین، برهان وجوب و امکان را با مفهوم «امکان فقری» ژرف کرد: ممکنات، تنها در «آغاز» به علّت نیاز ندارند؛ در هر لحظهٔ بودن، عین نیازند — «فقر» ذاتی‌شان است — چنان‌که نور لامپ، در هر لحظه، عین نیاز به برق است. این نگاه، توحید را از گزاره‌ای دربارهٔ آغاز جهان، به گزاره‌ای دربارهٔ همهٔ لحظه‌ها بدل می‌کند: «یا ایها الناس انتم الفقراء الی الله» — نه در آغاز، که اکنون — و هر دم. این تقریر، پل فلسفه به عرفان است؛ زیرا فقرِ ذاتی، همان «لا حول و لا قوة الا بالله» است که عارف، آن را نه گفتار، که وجود می‌یابد."]],
  ["دور و تسلسل؛ برهان‌های بطلان", "دور — توقف چیزی بر خودش با واسطه — و تسلسل — زنجیرهٔ بی‌پایان علل — در علل حقیقی، محال‌اند؛ و براهان الهیات، غالباً برای قطع این زنجیره‌اند. برهان دور روشن است: اگر الف به ب نیاز دارد و ب به الف، هیچ‌یک، هستی نمی‌گیرد — و این، بدیهی است. تسلسل ظریف‌تر است: چرا زنجیرهٔ بی‌پایان علل محال است؟ — نه برای اینکه ذهن از شمارش عاجز است، که برای اینکه هر حلقه، «ممکن» است و مجموعهٔ حلقه‌های ممکن، خود ممکن است و نیازمند مرجح — و مرجح، نمی‌تواند داخل زنجیره باشد. خواننده باید دقت کند که تسلسلِ علل «آماده‌کننده» — چون سلسلهٔ پدر و پسرها — محل بحث نیست؛ تسلسلِ علل «نگه‌دارنده» — علل بقا در همین لحظه — است که محال است.", ["کاربرد در کلام جدید", "در کلام جدید، برخی گفته‌اند اگر جهان قدیم باشد — بی آغاز زمانی — تسلسلِ حوادث لازم نمی‌آید تا به برهان نیاز باشد. پاسخ صدرایی — با امکان فقری — این است: مسئله، شمارش حوادث نیست؛ حتی یک لحظهٔ جهان، برای بودن، به غیر نیاز دارد؛ و این نیاز، در همین لحظه است — پس قدم زمانی جهان — اگر هم فرض شود — بی‌نیازی‌اش را ثابت نمی‌کند. این پاسخ، برهان را از گزندِ فرضِ قدم زمانی، مصون می‌دارد — و نشان می‌دهد که بحث حدوث و قدم زمانی، مهم است، اما مسئلهٔ اول نیست؛ مسئلهٔ اول، «فقر وجودی» است — و این، هم بر جهانِ حادث صادق است و هم بر جهانِ قدیم."]],
  ["برهان صدیقین؛ راهِ کوتاه", "برهان صدیقین — راه صدیقان — برهانی است که از خودِ وجود، به خدا می‌رسد، بی‌واسطهٔ مخلوقات: وجود، حقیقتی است واحد و مشکک؛ و هر مرتبه‌ای از آن، جز مرتبهٔ محض، محدود و ممکن است؛ پس باید مرتبه‌ای باشد که عین وجود است و هیچ حدّی ندارد — و آن، واجب‌الوجود است. ابن‌سینا تقریری از این برهان دارد و صدرالمتألهین، آن را با اصالت وجود، به اوج رساند: «الوجود بما هو وجود، لا یحتاج الی شیء» — وجود، از آن رو که وجود است، به غیر نیاز ندارد؛ و آنچه نیاز دارد، «حدّ وجود» است — و حد، نه از خود، که از وجود می‌گیرد. این برهان، «شرف» برهان‌ها خوانده می‌شود؛ زیرا شاهد را بی‌واسطهٔ گواه می‌بیند: خدا را از خود خدا می‌شناسد — «یا من دلّ علی ذاته بذاته».", ["چرا صدیقین؟", "نامِ این برهان — صدیقین — از این رو است که صدیق، حقیقت را بی‌واسطهٔ سایه‌ها می‌بیند؛ و این برهان نیز، از «آثار» نمی‌گذرد تا به «مؤثر» برسد — که در آثار می‌ماند و از خودِ آثار، خودِ مؤثر را می‌بیند. برهان نظم، از جهان به خدا می‌رود — و جهان، می‌تواند مورد تردید شود؛ اما برهان صدیقین، از حقیقتِ هستی — که هیچ شک‌پذیری در خودِ «هستی» نیست — آغاز می‌شود. این برهان، پاسخ فلسفهٔ اسلامی به نقد کانت بر براهین الهی است: کانت، برهان وجودیِ انسلمی را نقد کرد — که از مفهوم خدا به وجود او می‌پرد؛ اما برهان صدیقین، از مفهوم نمی‌پرد؛ از «حقیقتِ موجود» — از هستی‌ای که همین اکنون هست — به هستیِ محض می‌رود."]],
  ["برهان نظم؛ جهان به‌مثابه آیه", "برهان نظم — جهان، نظمی هدفمند دارد؛ و نظم هدفمند، ناظم می‌خواهد — کهن‌ترین و عامه‌فهم‌ترین برهان است. قرآن، بیش از آنکه برهان فلسفی بیاورد، به «آیات» ارجاع می‌دهد: «سنریهم آیاتنا فی الآفاق و فی انفسهم» — و سنت اسلامی، این راه را «دعوت از طریق آفاق و انفس» خوانده است. در عصر جدید، داروین با «انتخاب طبیعی»، تبیینی بی‌ناظم برای نظمِ زیستی پیشنهاد کرد — و این، برهان نظم را از صورت ساده‌اش خلع کرد؛ اما صورت ژرف‌تر — که از خودِ «قانونمندی طبیعت» و «قابلیت فهم جهان» می‌پرسد — باقی ماند: چرا طبیعت، اساساً قانونمند است؟ و چرا ذهن ما با این قوانین هماهنگ؟ این پرسش‌ها، امروز نیز زنده‌اند — و فلاسفه‌ای چون سویین‌برن، بر پایهٔ آن‌ها، برهان نظم را بازسازی کرده‌اند.", ["حدود برهان نظم", "برهان نظم، دو حد دارد که باید شناخت: نخست، این برهان، به خدایی می‌رسد که «طراح» است — نه لزوماً به واجب‌الوجودِ یگانهٔ فلسفی؛ و از این روست که فلاسفهٔ اسلامی، آن را کافی ندانسته و به برهان وجوب و امکان یا صدیقین ارجاع داده‌اند. دوم، این برهان، با تبیین‌های علمی — چون داروین — رقابت نمی‌کند؛ زیرا پرسش علم، «چگونه؟» است و پرسش برهان، «چرا اساساً؟» — و خلط این دو، هم به علم ظلم است و هم به برهان. خواننده باید این دو حد را بداند تا نه برهان را در دعوای زیست‌شناسی خرج کند، نه علم را در پاسخ‌گویی به «چرای بنیادین»."]],
  ["صفات خدا؛ ثبوتیه و سلبیه", "خداشناسی فلسفی، صفات خدا را به دو قسم می‌خواند: «سلبیه» — آنچه باید از او نفی کرد، چون جسمیت و تغییر و نیاز — و «ثبوتیه» — آنچه باید به او اثبات کرد، چون علم و قدرت و حیات. منطق این تقسیم، از تنزیه می‌آید: ما خدا را می‌شناسیم، اما نه چنان‌که خود را؛ و هر صفتی که از تجربه می‌گیریم، باید نخست پالایش شود. از این روست که متکلمان گفتند صفات خدا، «عین ذات» اوست — علمش، زاید بر ذاتش نیست — وگرنه ترکیب لازم می‌آید؛ و این تقریر، از دشوارترین و مهم‌ترین مباحث کلام امامی است که علامه حلی و صدوق، دربارهٔ حدود آن، بحث‌ها دارند.", ["تشبیه و تعطیل؛ دو آفت", "در صفات، دو آفت در کمین است: «تشبیه» — خدا را چون خلق پنداشتن — که قرآن با «لیس کمثله شیء» آن را بسته است؛ و «تعطیل» — چنان نفی کردن صفات که خدا به «هیچ» بدل شود — که ائمه نیز با آن جنگیده‌اند: «لا یوصف بکیف و لا بأین» — نه با چگونگی وصف می‌شود، نه نفی مطلق. راه میانه، «اثبات بی تشبیه» است: علم و قدرت و حیات را به او نسبت می‌دهیم، اما نه چون علم ما — که محدود و زاید و اکتسابی است — که به نحوِ کمالِ وجودی. این راه، با اصالت وجود، تقریر فلسفی می‌یابد: صفات خدا، مراتبِ کمالِ وجودند — و وجودِ محض، همهٔ کمالات را — بی حدّ — داراست."]],
  ["علم الهی؛ پیش و پس از پیدایش", "علم خدا به جهان، از دشوارترین مباحث الهیات است: چگونه خدا جزئیاتِ متغیر را — که هر لحظه دگرگون‌اند — می‌داند، بی‌آنکه علمش دگرگون شود؟ ابن‌سینا گفت: خدا جزئیات را «به نحو کلی» می‌داند — و این تقریر، در کلام، نقد شد که «خدا جزئی را جزئی نمی‌داند، نقص است». صدرالمتألهین با «علم حضوری» و نظریهٔ «نفس الامر»، پاسخی دیگر داد: علم خدا، از راه «صور» نیست تا با تغییر معلوم دگرگون شود؛ علم او، حضوری است — و حضور، با تغییرِ حاضرشونده، دگرگون نمی‌شود؛ چنان‌که علم ما به «گذشت زمان»، با گذشت زمان دگرگون نمی‌شود. این بحث، در عمل، به مسئلهٔ دعا و قضا و قدر می‌رسد — و پاسخ درست به آن، شرط حل بسیاری از گره‌های اعتقادی است.", ["علم پیشین و اختیار", "شبههٔ مشهور: اگر خدا پیش از عمل من، می‌داند که چه می‌کنم، پس من ناچارم — و اختیار باطل است. پاسخ کلاسیک — از علامه تا صدراییان — این است: علم، «کاشف» است، نه «موجب»: علم خدا به عمل من، به این تعلق گرفته که «من، مختارانه این عمل را می‌کنم» — و اگر من ناگزیر می‌بودم، علم خدا به «اختیارِ من» خطا بود — که محال است. به عبارت دقیق‌تر: علم خدا، به عملِ منِ مختار تعلق دارد؛ پس علم، با اختیار ناسازگار نیست — بلکه خودِ «علم به اختیار» است. این پاسخ، ظرافتی دارد که باید با دقت خواند — و خلط «کاشفیت» و «علیت» را باید یک‌بار برای همیشه شناخت."]],
  ["قدرت و اراده الهی", "قدرت خدا، یعنی او بر هر «ممکنی» تواناست — نه بر محال؛ زیرا محال، «چیز» نیست که بر آن توانا بود — «آیا خدا می‌تواند سنگی بیافریند که خود نتواند بلند کند؟» پرسشی است که از خلط قدرت و محال می‌آید. و ارادهٔ او — بنا بر حکمت — عین علم او به نظام احسن است: او جهان را می‌خواهد چون نظام احسن را می‌داند — و این تقریر صدرایی، اراده را از «هوس» بیرون می‌آورد و با حکمت یکی می‌کند. در برابر، اشاعره اراده را از حکمت جدا دانستند — «یفعل ما یشاء» — و از این رو، حسن و قبح را نیز به شرع سپردند؛ و این اختلاف — ارادهٔ حکیم یا ارادهٔ مطلق — یکی از عمیق‌ترین اختلاف‌های کلام اسلامی است که در فقه — قاعدهٔ لطف و مصلحت — نیز اثر دارد.", ["شر و اراده", "اگر خدا همه‌چیز را می‌خواهد و تواناست، شر از کجاست؟ پاسخ حکمت متعالیه، چندلایه است: نخست، شرور، در عمده‌ترین قسم، «امور عدمی»‌اند — کوری، نبودِ بینایی است — و عدم، مخلوق نیست که به اراده نیاز داشته باشد. دوم، شرورِ وجودی — چون سوزاندن آتش — نسبت به نظام کل، خیرند؛ و شر بودنشان، نسبت به این جزء است. سوم، جهانِ ممکن، عالم تزاحم است — و تزاحم، لازمهٔ ماده است؛ و جهانی که تزاحم ندارد، جهان ماده نیست. این پاسخ‌ها — با مسئلهٔ اختیار انسان که شرور اخلاقی را به انسان می‌سپارد — دستگاهی می‌سازد که مسئلهٔ شر را نه حلِ آسان، که فهمِ درست می‌کند."]],
  ["خیر و شر؛ مسئلهٔ قدیمی", "مسئلهٔ شر — اگر خدای خیر و توانا هست، چرا شر هست؟ — از کهن‌ترین پرسش‌های بشر است. اپیکور صورت منطقی آن را ساخت؛ و در روزگار ما، پس از آشویتس، صورت وجودی آن — «اعتراض به خدا» — برجسته شد. پاسخ اسلامی، در سه ساحت است: ساحت منطقی — که شرور، یا عدمی‌اند یا لازمهٔ نظام ممکن —؛ ساحت معرفتی — که احاطهٔ ما بر نظام کل نیست و داوری جزئی بر کل، خطاست —؛ و ساحت وجودی — که رنج، می‌تواند معناساز باشد — چنان‌که در عرفان، بلا را «تربیت» خوانده‌اند. قرآن نیز، مسئله را نه فقط پاسخ، که «تأویل» می‌کند: «عسی ان تکرهوا شیئاً و هو خیر لکم» — و این «عسی»، نه انکار شر، که گشودن افقی است که در آن، شر، معنای خود را می‌گشاید.", ["شر و اختیار انسان", "بخش بزرگی از شرور جهان — ظلم، جنگ، فقرِ ساختاری — نه از طبیعت، که از انتخاب انسان‌اند؛ و این، بار مسئله را بر دوش «اختیار» می‌گذارد: جهانی که در آن انسان، واقعاً آزاد باشد، جهانی است که در آن انسان، می‌تواند ظلم کند. این پاسخ — که «اختیار، ارزشمندتر از آن است که برای جلوگیری از شر، گرفته شود» — با مسئولیتِ ما تمام می‌شود: اگر شرور از ماست، پاسخ به شر، نه فقط توجیه الهیاتی، که «عمل اخلاقی» است — و همین، پل مسئلهٔ شر به اخلاق و فقه و سیاست است. خواننده‌ای که مسئلهٔ شر را چنین ببیند، از بن‌بستِ اعتراض بیرون می‌آید و به میدان مسئولیت می‌رسد."]],
  ["جبر و اختیار؛ مسئلهٔ عمل", "آیا انسان در کارهایش آزاد است یا ناچار؟ این پرسش، انتزاعی نیست؛ زیرا اگر جبر باشد، تکلیف و پاداش و کیفر — و همهٔ اخلاق و حقوق — فرو می‌ریزد؛ و اگر تفویض مطلق باشد، توحید افعالی خدشه می‌خورد. تاریخ کلام، سه موضع ساخت: جبر — اشعریِ متشدد —؛ تفویض — معتزلی —؛ و «امر بین الامرین» — امامی —. برهانِ وجدانیِ اختیار، روشن است: هر کس، میان برداشتن و برنداشتن لیوان، تفاوتی را «می‌یابد» که میان تپش قلب و برداشتن نیست — و این یافتنِ حضوری، از هر برهانی محکم‌تر است. اما سؤال فلسفی، چگونگیِ جمع این اختیار با علم و اراده و قدرت الهی است — و پاسخ‌های آن، سلسلهٔ درس‌های بعدی است.", ["دو مغالطه در مسئله", "در مسئلهٔ جبر و اختیار، دو مغالطه رایج است: نخست، مغالطهٔ «علت و اجبار»: اینکه هر فعلی علّت دارد، به معنای آن نیست که فعل، «جبراً» است — اگر علّت، خودِ ارادهٔ آگاهانهٔ فاعل باشد، فعل، اختیاری است؛ پس «هر فعلی علّت دارد» و «انسان آزاد است» ناسازگار نیستند. دوم، مغالطهٔ «علم و اجبار»: علمِ پیشین خدا — چنان‌که گذشت — کاشف است، نه موجب. این دو مغالطه، ریشهٔ بیشتر تردیدها در مسئله‌اند — و خواننده‌ای که این دو را شناخت، نیمی از راه را پیموده است؛ نیمهٔ دیگر، فهم تقریرِ صدرایی از «امر بین الامرین» است."]],
  ["امر بین الامرین؛ تقریر صدرایی", "امام صادق (ع) فرمود: «لا جبر و لا تفویض بل امر بین الامرین» — و فلاسفهٔ صدرایی کوشیدند این «بین» را تبیین کنند. تقریر: فعل انسان، هم فعل اوست — زیرا با اراده و علم او صادر می‌شود — و هم فعل خدا — زیرا وجودِ این اراده و این فعل، از فیض اوست؛ و این دو، در دو مرتبه‌اند، نه در یک مرتبه که تناقض شود: انسان، فاعل است در مرتبهٔ خود؛ و خدا، فاعلِ فاعل است — «لا یؤثر الا باذنه». این تقریر — که به طولیت معروف است — هم تکلیف و مسئولیت را نگه می‌دارد و هم توحید افعالی را؛ و نشان می‌دهد که جبر و تفویض، نه دو پاسخ به یک پرسش، که دو خطای یکسان‌اند: دیدن خدا و انسان در یک ردیف.", ["نتایج اخلاقی و تربیتی", "امر بین الامرین، فقط نظریه‌ای کلامی نیست؛ نتایج تربیتی دارد: از جبر، سستی و بهانه‌جویی می‌روید — «مقسوم چنین بود» — و از تفویض، غرور و خودبینی — «من خود کردم»؛ و از امر بین الامرین، هم «تلاش» می‌روید — که کار از ماست — و هم «توکل و شکر» — که هستیِ کار از اوست. این ترکیب — کار کن و بدان که نیست از تو — روح اخلاق عملی سنت اسلامی است؛ و در ادب فارسی، از مولانا تا حافظ، پژواک دارد. خواننده‌ای که این درس را بفهمد، در برابر شکست، مغرور نمی‌شود و در برابر موفقیت، متکبر — و این، میوهٔ عملیِ دقیق‌ترین مباحث فلسفی است."]],
  ["نفس و تجرد آن", "نفس چیست؟ فلسفهٔ اسلامی، با برهان‌هایی چند، تجرد نفس را اثبات می‌کند: برهان انسان معلق — که گذشت —؛ برهان وحدت شخصیه — همانیِ من در طول زمان؛ برهان ادراک کلیات — که در ماده نمی‌گنجد؛ و برهان علم حضوری نفس به ذات. تجرد، یعنی نفس، نه جسم است و نه حالتِ جسم — نه در مغز، که مغز، ابزار اوست. این موضع، با فیزیکالیسم جدید — که ذهن را حالت مغز می‌داند — در تضاد است؛ و بحث میان این دو، از زنده‌ترین بحث‌های فلسفهٔ ذهن است. حکمت متعالیه، با حرکت جوهری، تبیین می‌کند که نفس، چگونه از دل طبیعت برمی‌خیزد بی‌آنکه طبیعت باشد — و این، از دقیق‌ترین تقریرهای مسئلهٔ ذهن-بدن در تاریخ فلسفه است.", ["مراتب تجرد", "تجرد، یک مرتبه نیست: «تجرد مثالی» — صورتی که ماده ندارد اما ویژگی‌های ماده — چون شکل و مکان — را دارد، چون صور خواب و خیال؛ «تجرد عقلی» — صورتی که از همهٔ ویژگی‌های مادی بری است، چون مفاهیم؛ و نفس انسان، در سیرش، از مرتبهٔ مادی به مثالی و از مثالی به عقلی می‌رود — «جسما الحدوث و روحانیا البقا». این مراتب، نقشهٔ معاد را نیز می‌سازد: برزخ، عالم تجرد مثالی است؛ و قیامت کبری، فعلیت کامل نفس است. خواننده می‌بیند که بحث «نفس»، نه یک مسئله، که شاهراهی است که از معرفت‌شناسی تا معاد، همه را به هم می‌دوزد."]],
  ["مراتب نفس؛ نباتی تا انسانی", "فلسفهٔ اسلامی — با پیروی از ارسطو — قوای نفس را سه مرتبه شمرد: «نباتی» — تغذیه و رشد و تولید مثل؛ «حیوانی» — ادراک جزئی و حرکت ارادی؛ و «انسانی» — عقل نظری و عملی. این تقسیم، صرفاً زیست‌شناسی نیست؛ برنامهٔ تربیت است: کسی که در مرتبهٔ نباتی می‌ماند — همهٔ همّش خوردن و خوابیدن است — از انسانیت غافل مانده؛ و کسی که در حیوانی می‌ماند — اسیر هیجان و تخیل است — به عقل نرسیده. و جالب آنکه هر مرتبه، مرتبهٔ پایین‌تر را «حمل» می‌کند و بر آن می‌افزاید — و این، همان نگاه تشکیکی است که در وجود دیدیم؛ اکنون در نفس. این نگاه، به علوم تربیتی نیز جهت می‌دهد: تربیت، نه انکار مراتب پایین، که سامان دادن آن‌ها در خدمت مرتبهٔ بالاتر است.", ["عقل نظری و عملی", "عقل انسانی، دو بال دارد: «نظری» — که حقایق را می‌فهمد — و «عملی» — که کارها را سامان می‌دهد. عقل نظری، از بدیهیات به نظریات می‌رود و به «عقل مستفاد» — مرتبه‌ای که حقایق بر آن حاضرند — می‌رسد؛ و عقل عملی، «بایدها» را می‌فهمد — که ریشهٔ حسن و قبح عقلی است. اخلاق و سیاست، میدان عقل عملی‌اند؛ و فلسفه و علم، میدان عقل نظری. این تفکیک — که در اخلاق نیکوماخوس نیز — با نام‌های سوفیا و فرونسیس — می‌بینیم — از مهم‌ترین میراث‌های مشترک دو سنت فلسفی است؛ و خلط این دو — چون پرسیدنِ «دانش علمی از اخلاق» یا «فتوای فلسفی» — از ریشه‌های آشفتگی‌های فکری معاصر است."]],
  ["نفس و بدن؛ پیوندی عجیب", "اگر نفس مجرد است، چگونه با بدنِ مادی پیوند دارد و بر آن اثر می‌گذارد؟ این — مسئلهٔ تعامل — از کهن‌ترین گره‌های فلسفهٔ ذهن است. دکارت، با غدهٔ صنوبری، پاسخ جسمانی داد — و شکست خورد؛ و موازی‌گرایان، تعامل را انکار کردند — که با وجدان ناسازد. صدرالمتألهین، با حرکت جوهری و نظریهٔ «وحدت نفس و بدن در سیر»، پاسخی دیگر داد: نفس و بدن، دو چیزِ جدا نیستند که پیوندشان پرسش شود؛ نفس، «مرتبهٔ فعلیتِ همین بدن» است — بدن و نفس، دو روی یک حقیقتِ سیال‌اند که از ماده آغاز و به تجرد می‌رسد. و از این رو، اثر نفس بر بدن، اثر روح بر ماشین نیست؛ اثر مرتبهٔ بالاترِ یک حقیقت بر مرتبهٔ پایین‌تر آن است — چنان‌که معنای جمله، بر حروفش اثر می‌گذارد.", ["پیامدهای این پاسخ", "پاسخ صدرایی، پیامدهای بزرگی دارد: نخست، مرگ، نه «جدا شدن دو چیز»، که «به فعلیت رسیدنِ نفس» است — بدن، چون پوسته‌ای که هنگام رشد می‌شکفد. دوم، تأثیر متقابل نفس و بدن — تأثیر غذا و ورزش بر روح، و تأثیر اخلاق بر سلامت — نه راز، که لازمِ وحدت آن دو است؛ و این، بنای فلسفی طب سنتی و روان‌تنی است. سوم، معاد جسمانی — بازگشت با بدن — نه بازسازی بدن کهنه، که فعلیت بدنِ حقیقیِ انسان است — بدنی که با نفس، از مرتبهٔ مادی گذشته است. این سه پیامد، نشان می‌دهد که یک پاسخ درست به «مسئلهٔ تعامل»، چگونه سه مسئلهٔ بزرگ را با هم حل می‌کند."]],
  ["قوای شناخت؛ از حس تا عقل", "راه شناخت انسان، نردبانی است چندپله: «حواس ظاهره» — بینایی و شنوایی و سه دیگر؛ «حواس باطنه» — حس مشترک که داده‌های حواس را یکپارچه می‌کند، خیال که صورت‌ها را نگه می‌دارد، متصرفه که ترکیب و تجزیه می‌کند، وهم که معانی جزئی — چون مهربانیِ مادر — را می‌فهمد، و حافظه. و فراتر از همه، «عقل» — که از صورت‌های جزئی، معانی کلی می‌سازد. این نقشه — که فارابی و ابن‌سینا سامانش دادند — هنوز برای شناختِ شناخت، راهنماست؛ زیرا جایگاه هر قوه و خطای خاص آن را می‌شناساند: چشم، رنگ را می‌بیند اما معنا را نمی‌فهمد؛ و وهم، معنا را می‌فهمد اما کلی را نمی‌سازد؛ و هر قوه‌ای که فراتر از جای خود داوری کند، خطا می‌کند.", ["خطای هر قوه", "هر قوه، خطای خاص خود را دارد — و شناخت این خطاها، نیمی از معرفت‌شناسی است: خطای حواس — سراب و اشتباهات بصری — با ابزار و دقت، اصلاح می‌شود؛ خطای خیال — درآمیختن صورت‌ها — با تمیز خیال از ادراک، شناخته می‌شود؛ و خطای وهم — بزرگ‌ترین — تعمیم معانی جزئی به حقایق است: وهم می‌گوید «هر چه هست، باید چون جسم باشد» — و این، ریشهٔ مادی‌گری خودانگیخته است. ابن‌سینا، وهم را «شیطان درون» خوانده؛ زیرا او است که عقل را به داوری در قلمروی او وامی‌دارد. و درمان — به تعبیر حکمای سنت — «ورزیدن عقل» است: چنان‌که چشم با عینک، وهم نیز با منطق و ریاضت فکری، اصلاح می‌شود."]],
  ["نبوت و وحی؛ معرفت برتر", "فلسفهٔ اسلامی، نبوت را نه فقط امر اعتقادی، که مسئله‌ای معرفت‌شناختی می‌خواند: اگر مراتب شناخت — از حس تا عقل — هست، چرا مرتبه‌ای برتر نباشد — مرتبه‌ای که حقایق را بی‌واسطهٔ استدلال، دریافت کند؟ ابن‌سینا، در شفا و نجات، نبوت را در همین دستگاه تبیین کرد: پیامبر، کسی است که «عقل قدسی»‌اش، به تماس با عقل فعال، حقایق را دریافت می‌کند — و «قوهٔ مخیلهٔ» قوی‌اش، آن حقایق را برای عامه، به صورت‌ها و تمثیل‌ها برمی‌گرداند. این تبیین — که کمال نبوت را در هر دو قوه می‌دید — راه را برای فهم «زبان تمثیلی وحی» گشود: قرآن، هم حقیقت است و هم مثال — و فهم درست، دیدن هر دو لایه است.", ["اعجاز؛ معیار صدق نبوت", "اگر ادعای دریافت برتر ممکن است، معیار صدق آن چیست؟ پاسخ سنت، «معجزه» است — رویدادی که از راه‌های متعارف برنمی‌آید و با ادعای نبوت همراه است. اما فلسفهٔ جدید، با تقریبِ قوانین طبیعت، امکان معجزه را به پرسش کشید. پاسخ صدرایی — با مراتب وجود — این است: قوانین طبیعت، قوانین مرتبهٔ مادی‌اند؛ و مرتبه‌های بالاتر — نفس و عقل — بر آن محیط‌اند؛ و آنچه از مرتبهٔ بالاتر در پایین ظاهر شود، برای پایین‌ترها «خارق» است — بی‌آنکه قانون مرتبهٔ خود را شکسته باشد. این پاسخ، معجزه را نه «نقض قانون»، که «ظهور مرتبه» می‌خواند — و با آن، مسئلهٔ کرامات و استجابت دعا نیز تقریرپذیر می‌شود."]],
  ["معاد؛ فلسفهٔ فرجام", "معاد — بازگشت و سرانجام — از ارکان سه‌گانهٔ عقیده است؛ و فلسفهٔ اسلامی، آن را با برهان می‌سنجد، نه فقط با نقل. برهان‌های معاد، چند راه دارند: راه «استعداد» — نفسی که در این جهان به فعلیت کامل نرسیده، بستر فعلیتِ بعدی است؛ راه «حکمت» — جهانی که در آن ظالم و مظلوم یکسان بمیرند، بی‌حکمت است؛ و راه «وجود» — که صدرایی است: نفس، جوهری سیال است که در طول حرکت جوهری، از ماده به تجرد می‌رود — و مرگ، پایان این حرکت نیست؛ نقطهٔ برآمدنِ نفس از پوستهٔ مادی است. این برهانِ آخر، معاد را نه «احیای دوباره»، که «ادامهٔ سیر وجودی» می‌خواند — و مرگ را از «نیستی» به «تولد» معنا می‌کند.", ["معاد جسمانی", "دشوارترین بحث معاد، معاد جسمانی است — بازگشت با بدن؛ زیرا قرآن، صریحاً از آن سخن می‌گوید و فلسفه، باید راه فهمش را بیابد. صدرالمتألهین، با حرکت جوهری و تجرد مثالی، پاسخ داد: بدنِ انسان، در طول زندگی، با نفس «یکی» می‌شود — و این یکی شدن، در مرگ، گسسته نمی‌شود؛ نفس، صورتِ بدنِ حقیقیِ خود را — که در مرتبهٔ مثال هست — با خود دارد و در قیامت، آن را فعلیت می‌بخشد. پس بدنِ برزخی و قیامتی، نه «بازسازی ذرات پوسیده»، که «فعلیت یافتن حقیقتی است که همیشه با نفس بوده». این تقریر، هم نص را نگه می‌دارد و هم برهان را — و نمونه‌ای است از هنر صدرایی در آشتی عقل و نقل."]],
  ["عالم مثال؛ جهان میانه", "«عالم مثال» — عالمی که صورت‌ها در آن مجرد از ماده‌اند اما ویژگی‌های ماده — چون شکل و اندازه و مکان — را دارند — از ابداعات سهروردی است که صدرالمتألهین آن را به ستون حکمت خود کرد. دلیل او: میان مادیِ محض و معقولِ محض، باید مرتبه‌ای میانه باشد — چنان‌که میان جسم و عقل، «نفس» هست. شاهد این عالم، متعدد است: خواب‌های صادقه — که صورت‌هایی دارند اما ماده ندارند؛ تخیل خلاق — که صحنه‌هایی می‌سازد؛ و مکاشفات عارفان. عالم مثال، جایگاه برزخ نیز هست — و با آن، مسئلهٔ «چگونه مردگان با هم‌اند» و «چگونه اعمال تجسم می‌یابند» — «یوم تبلی السرائر» — تقریرپذیر می‌شود: عمل، در مثال، صورت می‌گیرد — و آن صورت، در برزخ، دیده می‌شود.", ["مثال متصل و منفصل", "مثال، دو قسم است: «مثال متصل» — قوهٔ خیالِ انسان — که صورت‌های شخصی‌اش است؛ و «مثال منفصل» — عالمی که صورت‌هایش شخصی و همگانی‌اند — جهان برزخ. خلط این دو، از خطاهای رایج است: کسانی مکاشفات را صرفاً خیالِ متصل می‌دانند — و از این رو، بی‌ارزش می‌شمارند —؛ و عارفان می‌گویند مکاشفاتِ راستین، دیدنِ مثالِ منفصل است — که واقعیتی بیرون از ذهن دارد — و معیارش، سازگاری با شرع و عقل است. این تفکیک، هم از ساده‌لوحی می‌رهاند — که هر خیالی را وحی می‌پندارد — و هم از انکارگرایی — که هر تجربهٔ باطنی را توهم می‌خواند؛ و راه میانه، راه «سنجش» است — چنان‌که در هر شناخت دیگر."]],
  ["فلسفه و کلام؛ دو راه یک مقصد", "فلسفه و کلام، هر دو دربارهٔ خدا و جهان و انسان سخن می‌گویند — اما راهشان یکی نیست: کلام، از «عقاید نقلی» آغاز می‌کند و با عقل از آن‌ها دفاع می‌کند؛ و فلسفه، از «بدیهیات عقلی» آغاز می‌کند و به نتایج می‌رسد — حتی اگر با مشهور ناسازد. علامه طباطبایی، این تفاوت را چنین گفت: متکلم، چون وکیلی است که موکلش را — عقیده را — می‌شناسد و از آن دفاع می‌کند؛ و فیلسوف، چون قاضی است که بی‌پیش‌داوری به ادله می‌نگرد. هر دو راه، مشروع‌اند — و تاریخ اسلام، به هر دو نیاز داشته: کلام، مرزبان عقیده بوده و فلسفه، کاوشگر حقیقت؛ و در سنت شیعه، به‌ویژه پس از خواجه نصیر و علامه حلی، این دو به هم نزدیک شده‌اند — تا جایی که کلامِ متأخر، رنگ فلسفی گرفت و فلسفه، رنگ قرآنی.", ["خطرهای هر دو راه", "هر راهی، خطر خود را دارد: خطر کلام، «جدل‌زدگی» است — اینکه دفاع از عقیده، به هنرِ غلبه بدل شود و حقیقت، در غبار جدل گم شود — چنان‌که غزالی از متکلمان شکایت داشت. و خطر فلسفه، «غرور عقلی» است — اینکه فیلسوف، عقل را دادگاه همه‌چیز بداند و آنچه در دادگاهش نگنجد را منکر شود. درمان هر دو، «ادب» است: متکلم باید بداند که موکلش حقیقت است، نه پیروزی؛ و فیلسوف باید بداند که عقل، ابزاری است بزرگ — اما نه تنها ابزار. خواننده‌ای که این درس را بگیرد، هم از تعصب می‌رهد و هم از استبدادِ عقل — و این، میوهٔ بلوغ فکری است."]],
  ["فلسفه و عرفان؛ برهان و شهود", "رابطهٔ فلسفه و عرفان، از ظریف‌ترین روابط در میراث اسلامی است: فیلسوف، با برهان از هستی سخن می‌گوید؛ و عارف، با شهود — و این دو، گاه به یک نتیجه می‌رسند با دو زبان: وحدت وجود صدرایی و وحدت وجود عارفانه؛ معاد عقلی و «موت قبل ان تموتوا» عرفانی. اما دو راه، یکی نیستند: برهان، «دربارهٔ» حقیقت می‌گوید؛ و شهود، حقیقت را «می‌چشد» — و عارفان می‌گویند چشیدن، گواهیِ گفتن است، نه عین آن. صدرالمتألهین — که خود در هر دو وادی قدم داشت — کوشید این دو را در حکمت متعالیه بپیوندد: برهان، راه را هموار می‌کند و شهود، راه را می‌پیماید؛ و بی برهان، شهود به خیال می‌افتد، و بی شهود، برهان به پوسته می‌ماند.", ["معیار سنجش شهود", "اگر شهود، معرفتی است، معیار سنجشش چیست؟ عارفان سنت — از جنید تا امام خمینی — سه معیار شمرده‌اند: «شرع» — شهودی که با نص صریح ناسازد، مردود است؛ «عقل» — شهودی که با بدیهیات ناسازد، خیال است؛ و «ثمره» — شهود راستین، تقوا و اخلاق می‌آورد، نه ادعا و شطح. این سه معیار — که در درس آشنایی با عرفان نیز خواندیم — سپری است در برابر دو آفت: ساده‌لوحی و انکارگرایی. و خواننده باید بداند که فلسفه، در این مسئله، نه داورِ شهود، که هم‌راه اوست: هر دو، با معیارهای خود، راه را از بیراهه جدا می‌کنند — و این همکاری، از دستاوردهای بلوغ فکری سنت اسلامی است."]],
  ["فلسفهٔ جدید و پرسش‌هایش", "آشنایی با فلسفهٔ اسلامی، بی آشنایی با فلسفهٔ جدید، نیمه‌تمام است — زیرا بسیاری از پرسش‌های امروز، با زبان فلسفهٔ جدید طرح می‌شوند. فلسفهٔ جدید — از دکارت به بعد — سه چرخش داشت: «معرفت‌شناختی» — نخست بپرس چه می‌توانی بدانید؛ «زبانی» — نخست ببین چگونه می‌گویی؛ و امروز، «ذهن و شناخت» — نخست بفهم ذهن چیست. هر چرخش، پرسش‌هایی ساخت که سنت اسلامی، پیش از آن‌ها پاسخی داشته — اما نه با همین زبان: پرسش دکارت از یقین، در شک غزالی پیشینه دارد؛ و مسئلهٔ ذهن-بدن، در بحث نفس. خوانندهٔ مکتب‌خانه باید این پرسش‌ها را بشناسد — نه برای تقلید، که برای «گفت‌وگو»: سنتی که نتواند به پرسش‌های زمان خود پاسخ دهد، در موزه می‌ماند.", ["چالش‌های طبیعی‌گری و فیزیکالیسم", "بزرگ‌ترین چالش امروز فلسفهٔ دینی، «طبیعی‌گری» است — مدعای اینکه جز طبیعت، چیزی نیست و جز روش تجربی، راهی. این مدعا، در دو جبهه می‌جنگد: در معرفت‌شناسی — که یقین را به تجربه فرو می‌کاهد — و در فلسفهٔ ذهن — که شعور را به مغز فرو می‌کاهد. پاسخ سنت اسلامی، دوگانه است: نخست، طبیعی‌گری، خود با روش تجربی ثابت نمی‌شود — و این، تناقض خودویرانگر آن است؛ و دوم، تجربهٔ شعور — که هر کس مستقیم‌ترین شناختش است — در هیچ توصیف فیزیکی‌ای نمی‌گنجد — «شکاف تبیینی» که امروز حتی فیزیکالیست‌ها بدان اقرار دارند. خواننده می‌بیند که دفاع از تجرد نفس، نه دعوای کهنه، که زنده‌ترین دعوای فلسفهٔ امروز است."]],
  ["علم دینی و نسبت‌های آن", "در روزگار ما، پرسش «رابطهٔ علم و دین» از داغ‌ترین پرسش‌هاست — و فلسفهٔ اسلامی، برای پاسخ به آن، دستگاه دارد. چهار الگوی رابطه — تعارض، استقلال، گفت‌وگو، و یکپارچگی — را باربور شمرده؛ و سنت صدرایی، به یکپارچگی نزدیک است: علم و دین، دو خوانش از یک حقیقت‌اند — یکی با ابزار تجربه و یکی با ابزار عقل و وحی — و تعارض واقعی میان آن‌ها محال است؛ زیرا حقیقت، با حقیقت نمی‌جنگد. اما این یکپارچگی، نه به معنای «فیزیکِ قرآنی» است — که خلط زبان‌هاست — و نه به معنای جدایی کامل — که علم را بی‌ریشه می‌کند؛ که به معنای «وحدت در مراتب» است: هر دانش، در مرتبهٔ خود معتبر است و مراتب، بر هم نظارت دارند، نه حکومت.", ["پرسش‌های باز", "مسئلهٔ علم دینی، پرسش‌های بازی دارد که خوانندهٔ پژوهشگر باید با آن‌ها بماند: آیا پیش‌فرض‌های فلسفی — چون علیت و غایت — بر روش علمی اثر می‌گذارند؟ علوم انسانی — که موضوعشان انسانِ مختار است — چه نسبتی با علوم طبیعی دارند؟ و اخلاقِ پژوهش — که علم «باید» چه باشد — از کجا می‌آید؟ این پرسش‌ها، امروز، در فلسفهٔ علم — از کوهن تا مکینتایر — زنده‌اند؛ و سنت اسلامی — با تفکیک مراتب شناخت و قاعدهٔ سنخیت — حرف‌های تازه‌ای برای گفتن دارد. خواننده‌ای که این درس‌ها را خوانده، اکنون آماده است که در پروژهٔ پژوهشیِ سطح میانی، یکی از این پرسش‌ها را بکاود — و این، معنای «از خواندن به پژوهیدن رسیدن» است."]],
  ["جمع‌بندی؛ نقشهٔ راه حکمت", "اکنون که پنجاه درس فلسفه را پشت سر نهادیم، شایسته است به نقشهٔ کل بنگریم: از معرفت‌شناسی — شناخت حضوری و حصولی و معیار حقیقت — به هستی‌شناسی — وجود و ماهیت و تشکیک و علیت — رسیدیم؛ و از هستی‌شناسی به نفس‌شناسی — تجرد و مراتب — و از آن به خداشناسی — براهین و صفات — و سرانجام به فرجام‌شناسی — معاد و عالم مثال. این نظم، نه تصادفی است؛ نظم خودِ حقیقت است که از «من می‌دانم» به «من هستم» و از «من هستم» به «او هست» می‌رود. و هر مکتبی از این نقشه، راهی را رفته — و تفاوت مکاتب، در گام‌هایی است که بلندتر یا کوتاه‌تر برداشته‌اند.", ["به سوی بدایة و نهایة", "آموزش فلسفه، درگاه بود — و اکنون وقت ورود به متن‌های اصلی است. بدایة الحکمة علامه طباطبایی، این نقشه را در دوازده مرحلهٔ فشرده بازسازی می‌کند — با دقتی که متن درسی می‌طلبد؛ و نهایة الحکمة، همان مراحل را به اوج صدرایی می‌رساند؛ و آن‌کس که این سه را پیمود، آمادهٔ الاسفار است — متنی که در آن، صدرالمتألهین، چهار سفرِ سلوک عقلانی را روایت می‌کند. توصیهٔ پایانی: فلسفه را نه برای دانستن، که برای «توانا شدن در دیدن» بخوانید؛ زیرا فلسفه — به تعبیر علامه — نه انباشت نظریه‌ها، که ورزیدگیِ چشم است — چشمی که وقتی ورزیده شد، حقیقت را در هر چیز می‌بیند؛ و این، همان «حکمت» است که قرآن، اهلش را به «خیر کثیر» خوانده است."]],
];

